-- Product dictionary: stable keys, columns, types, links, and schema choices only.
PRAGMA foreign_keys=ON;
BEGIN;
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('activity','database','table','history','collection','work','table','activity','One activity definition in the work module.','Stable dictionary key for shipped commands.','Read activity.','CREATE TABLE activity (
  id INTEGER PRIMARY KEY AUTOINCREMENT, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL,
  field TEXT, old_value TEXT, new_value TEXT, actor TEXT NOT NULL, source TEXT, at TEXT NOT NULL, note TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('agent-soul','contract','agent-soul','playbooks','agent','base',NULL,'agents/<agent>.md; <workspace>/team/<seat>.md','One agent soul: the character and seat of one agent.','Without one soul, the same agent can act differently across runtimes.','agents/keeper.md holds the Keeper''s identity, what it owns, and its judgment.','Headers are Identity, What You Own, and Judgment. Paths start in the system home or the portfolio.','Ruled');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('agents','contract','agents','playbooks','workspace','base',NULL,'AGENTS.md','One agents definition in the base module.','Stable dictionary key for shipped commands.','Read AGENTS.md.','Required workspace content is purpose, records, skills and tools, approval gates, and routing.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('agreement','database','table','records','collection','people','table','agreements','One agreement definition in the people module.','Stable dictionary key for shipped commands.','Read agreements.','CREATE TABLE agreements (   id TEXT PRIMARY KEY NOT NULL,   agreement_family_id TEXT NOT NULL,   version TEXT NOT NULL,   opportunity_id TEXT REFERENCES opportunities(id),   counterparty_person_id TEXT REFERENCES persons(id),   counterparty_organization_id TEXT REFERENCES organizations(id),   type TEXT NOT NULL CHECK (type IN (''client'', ''creator'', ''ambassador'', ''vendor'')),   status TEXT NOT NULL DEFAULT ''draft'' CHECK (status IN (''draft'', ''sent'', ''signed'', ''expired'')),   start TEXT,   end TEXT,   value REAL,   currency TEXT,   file_path TEXT,   file_hash TEXT,   signed_at TEXT,   supersedes_id TEXT REFERENCES agreements(id),   rights_summary TEXT,   function TEXT,   evidence_refs TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(evidence_refs) AND json_type(evidence_refs) = ''array''),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE (agreement_family_id, version),   CHECK ((counterparty_person_id IS NOT NULL AND counterparty_organization_id IS NULL)       OR (counterparty_person_id IS NULL AND counterparty_organization_id IS NOT NULL)),   CHECK (start IS NULL OR end IS NULL OR end >= start) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('approvals','database','table','history','collection','work','table','approvals','One approvals definition in the work module.','Stable dictionary key for shipped commands.','Read approvals.','CREATE TABLE approvals (
  id INTEGER PRIMARY KEY AUTOINCREMENT, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, version TEXT,
  call TEXT NOT NULL CHECK (call IN (''approve'',''discuss'',''wrong'',''edit'')), person_words TEXT, given_at TEXT NOT NULL, source TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('attachments','database','table','history','collection','work','table','attachments','One attachments definition in the work module.','Stable dictionary key for shipped commands.','Read attachments.','CREATE TABLE attachments (
  id INTEGER PRIMARY KEY AUTOINCREMENT, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL,
  path TEXT NOT NULL, role TEXT, author TEXT, at TEXT, hash TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('base-soul','contract','base-soul','playbooks','agent','base',NULL,'agents/soul.md','The base soul holds the culture shared word for word by every agent.','Without shared culture, each agent can use different behavior standards.','Every agent loads the same agents/soul.md from the system home.','Headers are Core Truths, How You Think, Vibe (with How It Sounds), Boundaries, and How We Work.','Ruled');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('book','document','book','knowledge','collection','wiki',NULL,'memory/<native-book-path>.md','One book definition in the wiki module.','Stable dictionary key for shipped commands.','Read memory/<native-book-path>.md.','Keep exact source evidence separate when needed.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('brand','contract','brand','knowledge','workspace','design',NULL,'BRAND.md','One brand definition in the design module.','Stable dictionary key for shipped commands.','Read BRAND.md.','Include audience, voice, and the never list.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('bugs','database','table','records','collection','work','table','bugs','One bugs definition in the work module.','Stable dictionary key for shipped commands.','Read bugs.','Installed from the work module blueprint.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('capabilities','document','capabilities',NULL,'workspace','base',NULL,'CAPABILITIES.md','One capabilities definition in the base module.','Stable dictionary key for shipped commands.','Read CAPABILITIES.md.','Generate it from real definitions. Human editors do not maintain entries.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('claude','contract','claude','playbooks','workspace','base',NULL,'CLAUDE.md','One claude definition in the base module.','Stable dictionary key for shipped commands.','Read CLAUDE.md.','Use type claude. Keep only real Claude-specific differences and stay within 30 lines.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('comments','database','table','history','collection','work','table','comments','One comments definition in the work module.','Stable dictionary key for shipped commands.','Read comments.','CREATE TABLE comments (
  id INTEGER PRIMARY KEY AUTOINCREMENT, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL,
  author TEXT NOT NULL, at TEXT NOT NULL, body TEXT NOT NULL, reply_to INTEGER REFERENCES comments(id))','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('content','database','table','records','collection','design','table','content','One content definition in the design module.','Stable dictionary key for shipped commands.','Read content.','CREATE TABLE content (     id TEXT PRIMARY KEY NOT NULL,     content_family_id TEXT NOT NULL,     version TEXT NOT NULL,     owner TEXT NOT NULL,     function TEXT NOT NULL,     channel TEXT NOT NULL,     status TEXT NOT NULL,     format TEXT,     file_path TEXT NOT NULL,     file_hash TEXT NOT NULL,     brief_ref TEXT NOT NULL,     brief_hash TEXT,     source_url TEXT,     parent_content_id TEXT REFERENCES content(id),     creator_cycle_id TEXT,     deliverable_id TEXT,     creator_id TEXT,     media_file_id TEXT,     platform TEXT,     post_id TEXT,     published_at TEXT,     cataloged_at TEXT NOT NULL,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     evidence_refs TEXT NOT NULL DEFAULT ''[]''         CHECK (json_valid(evidence_refs) AND json_type(evidence_refs) = ''array''),     shared_interaction_id TEXT,     approval_ref TEXT,     approved_by TEXT CHECK (approved_by IS NULL OR approved_by = ''@Person@''),     approved_at TEXT,     accepted_hash TEXT,     UNIQUE (content_family_id, version),     CHECK (         (approval_ref IS NULL AND approved_by IS NULL          AND approved_at IS NULL AND accepted_hash IS NULL)         OR         (approval_ref IS NOT NULL AND length(trim(approval_ref)) > 0          AND approved_by IS NOT NULL AND approved_by = ''@Person@''          AND approved_at IS NOT NULL AND length(trim(approved_at)) > 0          AND accepted_hash IS NOT NULL AND accepted_hash = file_hash)     ) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('decisions','database','table','records','collection','work','table','decisions','One decisions definition in the work module.','Stable dictionary key for shipped commands.','Read decisions.','CREATE TABLE decisions (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, statement TEXT, person_words TEXT,
  status TEXT NOT NULL CHECK (status IN (''open'',''soft'',''ruled'',''deferred'',''withdrawn'',''superseded'')),
  replaces TEXT REFERENCES decisions(id), path TEXT, project TEXT, function TEXT, tags TEXT,
  decided_on TEXT, in_artifact INTEGER DEFAULT 0, artifact_version INTEGER, source TEXT, extra TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('design','contract','design','playbooks','workspace','design',NULL,'DESIGN.md','One design definition in the design module.','Stable dictionary key for shipped commands.','Read DESIGN.md.','Use the full ruled design framework. Do not stamp a draft framework as approved.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('eisenhower','database','view','records','collection','work','view','eisenhower','One eisenhower definition in the work module.','Stable dictionary key for shipped commands.','Read eisenhower.','CREATE VIEW eisenhower AS SELECT id,title,project,
  CASE WHEN important=1 AND urgent=1 THEN 1 WHEN important=1 THEN 2 WHEN urgent=1 THEN 3 ELSE 4 END AS box
  FROM tasks WHERE status NOT IN (''done'',''canceled'') ORDER BY box, deadline','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('functions','database','table','records','collection','work','table','functions','One functions definition in the work module.','Stable dictionary key for shipped commands.','Read functions.','CREATE TABLE functions (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, organization TEXT, parent TEXT REFERENCES functions(id), owner TEXT, page TEXT, tags TEXT, created_on TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('glossary','document','glossary','knowledge','workspace','base',NULL,'GLOSSARY.md','One glossary definition in the base module.','Without one glossary, agents can use the same word differently.','Read GLOSSARY.md.','Keep business words, model meanings, and approved vocabulary pointers.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('goals','database','table','records','collection','work','table','goals','One goals definition in the work module.','Stable dictionary key for shipped commands.','Read goals.','CREATE TABLE goals (
  id TEXT PRIMARY KEY, title TEXT NOT NULL,
  horizon TEXT NOT NULL CHECK (horizon IN (''north-star'',''3-year'',''1-year'',''quarter'')), period TEXT,
  function TEXT REFERENCES functions(id), owner TEXT,
  status TEXT NOT NULL DEFAULT ''on-track'' CHECK (status IN (''on-track'',''at-risk'',''off-track'',''done'',''dropped'')), tags TEXT, created_on TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('handle','database','table','records','collection','people','table','handles','One handle definition in the people module.','Stable dictionary key for shipped commands.','Read handles.','CREATE TABLE handles (   id TEXT PRIMARY KEY NOT NULL,   person_id TEXT REFERENCES persons(id),   channel TEXT NOT NULL,   account TEXT NOT NULL,   address TEXT NOT NULL,   source_contact_id TEXT,   verified_at TEXT,   evidence_ref TEXT,   function TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE (channel, account, address) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('incidents','database','table','history','collection','work','table','incidents','One incidents definition in the work module.','Stable dictionary key for shipped commands.','Read incidents.','Installed from the work module blueprint.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('log-entry','document','log-entry','history','workspace','base',NULL,'log-YYYY-MM.jsonl','One log-entry definition in the base module.','Stable dictionary key for shipped commands.','Read log-YYYY-MM.jsonl.','The log skill is the only writer. One object occupies one line.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('measure_history','database','trend','history','collection','work','trend','measure_history','One measure_history definition in the work module.','Stable dictionary key for shipped commands.','Read measure_history.','CREATE TABLE measure_history (
  measure TEXT NOT NULL REFERENCES measures(id), as_of TEXT NOT NULL, value REAL, note TEXT, PRIMARY KEY (measure, as_of))','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('measures','database','table','records','collection','work','table','measures','One measures definition in the work module.','Stable dictionary key for shipped commands.','Read measures.','CREATE TABLE measures (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, function TEXT REFERENCES functions(id), goal TEXT REFERENCES goals(id), owner TEXT,
  target REAL, unit TEXT, source TEXT, created_on TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('meeting','database','table','records','collection','people','table','meetings','One meeting definition in the people module.','Stable dictionary key for shipped commands.','Read meetings.','CREATE TABLE meetings (   id TEXT PRIMARY KEY NOT NULL,   title TEXT NOT NULL,   happened_at TEXT NOT NULL,   ended_at TEXT,   thread_id TEXT REFERENCES threads(id),   person_id TEXT REFERENCES persons(id),   organization_id TEXT REFERENCES organizations(id),   opportunity_id TEXT REFERENCES opportunities(id),   summary TEXT,   transcript_path TEXT,   source_url TEXT,   function TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   CHECK (ended_at IS NULL OR ended_at >= happened_at) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('message','database','mirror','history','collection','people','mirror','messages','One message definition in the people module.','Stable dictionary key for shipped commands.','Read messages.','CREATE TABLE messages (   channel TEXT NOT NULL,   source_account_id TEXT NOT NULL,   source_message_id TEXT NOT NULL,   source_thread_id TEXT NOT NULL,   sender_handle_id TEXT,   recipient_handle_ids TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(recipient_handle_ids) AND json_type(recipient_handle_ids) = ''array''),   workspace_tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(workspace_tags) AND json_type(workspace_tags) = ''array''),   sent_at TEXT,   direction TEXT CHECK (direction IN (''inbound'', ''outbound'', ''unknown'')),   source_url TEXT,   body_ref TEXT,   delivery_state TEXT,   content_hash TEXT,   source_system TEXT NOT NULL,   source_record_key TEXT,   source_updated_at TEXT,   observed_at TEXT,   pulled_at TEXT NOT NULL,   refresh_run_id TEXT,   source_hash TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   PRIMARY KEY (channel, source_account_id, source_message_id),   FOREIGN KEY (channel, source_account_id, source_thread_id)     REFERENCES threads(channel, source_account_id, source_thread_id) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('needs_me','database','view','records','collection','work','view','needs_me','One needs_me definition in the work module.','Stable dictionary key for shipped commands.','Read needs_me.','CREATE VIEW needs_me AS SELECT id,title,status,project,planned FROM tasks WHERE flag=1 AND status NOT IN (''done'',''canceled'') ORDER BY deadline, id','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('next_step','database','view','records','collection','work','view','next_step','One next_step definition in the work module.','Stable dictionary key for shipped commands.','Read next_step.','CREATE VIEW next_step AS SELECT id,title,status,parent,ord FROM tasks WHERE parent IS NOT NULL AND status IN (''todo'',''in-progress'') ORDER BY parent, ord LIMIT 1','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('open_decisions','database','view','records','collection','work','view','open_decisions','One open_decisions definition in the work module.','Stable dictionary key for shipped commands.','Read open_decisions.','CREATE VIEW open_decisions AS SELECT id,name,status,decided_on FROM decisions WHERE status IN (''open'',''soft'') ORDER BY decided_on','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('open_tasks','database','view','records','collection','work','view','open_tasks','One open_tasks definition in the work module.','Stable dictionary key for shipped commands.','Read open_tasks.','CREATE VIEW open_tasks AS SELECT id,title,status,project,owner,planned,deadline,important,urgent,flag FROM tasks
  WHERE status NOT IN (''done'',''canceled'') AND parent IS NULL ORDER BY urgent DESC, important DESC, deadline, id','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('opportunity','database','table','records','collection','people','table','opportunities','One opportunity definition in the people module.','Stable dictionary key for shipped commands.','Read opportunities.','CREATE TABLE opportunities (   id TEXT PRIMARY KEY NOT NULL,   title TEXT NOT NULL,   person_id TEXT REFERENCES persons(id),   organization_id TEXT REFERENCES organizations(id),   primary_handle_id TEXT REFERENCES handles(id),   pipeline TEXT NOT NULL REFERENCES pipelines(id),   stage TEXT NOT NULL,   outcome TEXT NOT NULL DEFAULT ''open'' CHECK (outcome IN (''open'', ''won'', ''lost'', ''abandoned'')),   value REAL,   currency TEXT,   offer_summary TEXT,   owner TEXT,   function TEXT,   external_opportunity_ref TEXT,   source_checked_at TEXT,   evidence_refs TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(evidence_refs) AND json_type(evidence_refs) = ''array''),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   FOREIGN KEY (pipeline, stage) REFERENCES pipeline_stages(pipeline, stage) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('organization','database','table','records','collection','people','table','organizations','One organization definition in the people module.','Stable dictionary key for shipped commands.','Read organizations.','CREATE TABLE organizations (   id TEXT PRIMARY KEY NOT NULL,   name TEXT NOT NULL,   domain TEXT,   note_path TEXT,   function TEXT,   evidence_refs TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(evidence_refs) AND json_type(evidence_refs) = ''array''),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('organization-membership','database','table','records','collection','people','table','organization_memberships','One organization-membership definition in the people module.','Stable dictionary key for shipped commands.','Read organization_memberships.','CREATE TABLE organization_memberships (   id TEXT PRIMARY KEY NOT NULL,   person TEXT NOT NULL REFERENCES persons(id),   organization TEXT NOT NULL REFERENCES organizations(id),   role TEXT,   starts_on TEXT,   ends_on TEXT,   evidence_ref TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   CHECK (starts_on IS NULL OR ends_on IS NULL OR ends_on >= starts_on) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('page','document','page','knowledge','collection','wiki',NULL,'memory/<native-page-path>.md','One page definition in the wiki module.','Stable dictionary key for shipped commands.','Read memory/<native-page-path>.md.','Keep it current and distinct from dated notes.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('participant','database','table','records','collection','people','table','participants','One participant definition in the people module.','Stable dictionary key for shipped commands.','Read participants.','CREATE TABLE participants (   id TEXT PRIMARY KEY NOT NULL,   thread_id TEXT NOT NULL REFERENCES threads(id),   person_id TEXT REFERENCES persons(id),   handle_id TEXT REFERENCES handles(id),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   CHECK (person_id IS NOT NULL OR handle_id IS NOT NULL),   UNIQUE (thread_id, person_id),   UNIQUE (thread_id, handle_id) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('person','database','table','records','collection','people','table','persons','One person definition in the people module.','Stable dictionary key for shipped commands.','Read persons.','CREATE TABLE persons (   id TEXT PRIMARY KEY NOT NULL,   display_name TEXT NOT NULL,   portfolio_person_id TEXT,   aliases TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(aliases) AND json_type(aliases) = ''array''),   primary_comms_channel TEXT,   note_path TEXT,   function TEXT,   source_refs TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(source_refs) AND json_type(source_refs) = ''array''),   evidence_refs TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(evidence_refs) AND json_type(evidence_refs) = ''array''),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('pipeline','database','table','records','collection','people','table','pipelines','One pipeline definition in the people module.','Stable dictionary key for shipped commands.','Read pipelines.','CREATE TABLE pipelines (   id TEXT PRIMARY KEY NOT NULL,   name TEXT NOT NULL,   function TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('pipeline-stage','database','table','records','collection','people','table','pipeline_stages','One pipeline-stage definition in the people module.','Stable dictionary key for shipped commands.','Read pipeline_stages.','CREATE TABLE pipeline_stages (   pipeline TEXT NOT NULL REFERENCES pipelines(id),   stage TEXT NOT NULL,   ord INTEGER NOT NULL CHECK (typeof(ord) = ''integer'' AND ord >= 0),   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   PRIMARY KEY (pipeline, stage),   UNIQUE (pipeline, ord) )','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('projects','database','table','records','collection','work','table','projects','One projects definition in the work module.','Stable dictionary key for shipped commands.','Read projects.','CREATE TABLE projects (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, result TEXT, goal TEXT REFERENCES goals(id),
  status TEXT NOT NULL DEFAULT ''backlog'' CHECK (status IN (''backlog'',''todo'',''in-progress'',''done'',''canceled'')),
  function TEXT REFERENCES functions(id), owner TEXT, due TEXT, page TEXT, tags TEXT, created_on TEXT, extra TEXT,
  description TEXT, problem TEXT, job_when TEXT, job_want TEXT, job_so TEXT, done_when TEXT, context TEXT, ord INTEGER)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('quote','document','quote','history','collection','wiki',NULL,'raw/<native-quote-path>.md','One quote definition in the wiki module.','Stable dictionary key for shipped commands.','Read raw/<native-quote-path>.md.','Keep the citation before compiling it into knowledge.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('record_links','database','table','records','collection','work','table','record_links','One record_links definition in the work module.','Stable dictionary key for shipped commands.','Read record_links.','Installed from the work module blueprint.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('resolver','contract','resolver','playbooks','workspace','base',NULL,'RESOLVER.md','One resolver definition in the base module.','Stable dictionary key for shipped commands.','Read RESOLVER.md.','Use type resolver. Replace stale homes with current row, file, or outside-source homes.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('schema','view','schema','knowledge','workspace','base',NULL,'SCHEMA.md','A generated page: every object type with its fields and meanings, plus the ERD.','Agents query the rows; the page is a readable view that nobody edits.','SCHEMA.md is built from the object_types and fields rows.','Generated view in the dictionary collection. Change the rows, then rebuild the page.','Ruled');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('task_links','database','table','records','collection','work','table','task_links','One task_links definition in the work module.','Stable dictionary key for shipped commands.','Read task_links.','CREATE TABLE task_links (
  id INTEGER PRIMARY KEY AUTOINCREMENT, task TEXT NOT NULL REFERENCES tasks(id),
  system TEXT NOT NULL, scope TEXT, external_id TEXT, path TEXT, relation TEXT NOT NULL,
  active INTEGER DEFAULT 1, created_on TEXT, UNIQUE (task, system, external_id))','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('tasks','database','table','records','collection','work','table','tasks','One tasks definition in the work module.','Stable dictionary key for shipped commands.','Read tasks.','CREATE TABLE tasks (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT,
  status TEXT NOT NULL DEFAULT ''todo'' CHECK (status IN (''backlog'',''todo'',''in-progress'',''blocked'',''done'',''canceled'')),
  project TEXT REFERENCES projects(id), function TEXT REFERENCES functions(id), tags TEXT,
  owner TEXT, created_by TEXT, claimed_by TEXT, claimed_at TEXT, blocked_by TEXT REFERENCES tasks(id), done_check TEXT,
  parent TEXT REFERENCES tasks(id), ord INTEGER,
  planned TEXT, deadline TEXT, important INTEGER DEFAULT 0, urgent INTEGER DEFAULT 0, flag INTEGER DEFAULT 0,
  idempotency_key TEXT UNIQUE, created_on TEXT, source TEXT, extra TEXT, goal TEXT REFERENCES goals(id),
  note TEXT, acceptance TEXT, context TEXT)','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('template','document','template','playbooks','module','base',NULL,'<owning-module-or-skill>/templates/<name>','One template definition in the base module.','Stable dictionary key for shipped commands.','Read <owning-module-or-skill>/templates/<name>.','Keep it with the skill or module that consumes it.','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('this_week','database','view','records','collection','work','view','this_week','One this_week definition in the work module.','Stable dictionary key for shipped commands.','Read this_week.','CREATE VIEW this_week AS SELECT id,title,status,project,planned,deadline FROM tasks
  WHERE status NOT IN (''done'',''canceled'') AND (planned <= date(''now'',''+7 days'') OR deadline <= date(''now'',''+7 days'')) ORDER BY planned, deadline','base/dictionary-seed.sql');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('thread','database','table','records','collection','people','table','threads','One thread definition in the people module.','Stable dictionary key for shipped commands.','Read threads.','CREATE TABLE threads (   id TEXT PRIMARY KEY NOT NULL,   channel TEXT NOT NULL,   source_account_id TEXT NOT NULL,   source_thread_id TEXT NOT NULL,   title TEXT,   workspace_tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(workspace_tags) AND json_type(workspace_tags) = ''array''),   status TEXT NOT NULL DEFAULT ''open'' CHECK (status IN (''open'', ''closed'')),   function TEXT,   tags TEXT NOT NULL DEFAULT ''[]'' CHECK (json_valid(tags) AND json_type(tags) = ''array''),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE (channel, source_account_id, source_thread_id) )','base/dictionary-seed.sql');
