-- T706: repair contract rows that an older install wrote. Guarded by the stale value, so a second run changes nothing.
UPDATE object_types SET "supertype"='contract', "subtype"='agent-soul', "lens"='playbooks', "container"='agent', "module"='base', "storage_name"='agents/<agent>.md; <workspace>/team/<seat>.md', "description"='One agent soul: the character and seat of one agent.', "why"='Without one soul, the same agent can act differently across runtimes.', "example"='agents/keeper.md holds the Keeper''s identity, what it owns, and its judgment.', "definition"='Headers are Identity, What You Own, and Judgment. Paths start in the system home or the portfolio.', "source"='Ruled' WHERE name='agent-soul' AND (storage_name LIKE '%/Code/agent-team/%' OR storage_name = 'team/<agent>.md');
UPDATE object_types SET "supertype"='contract', "subtype"='base-soul', "lens"='playbooks', "container"='agent', "module"='base', "storage_name"='agents/soul.md', "description"='The base soul holds the culture shared word for word by every agent.', "why"='Without shared culture, each agent can use different behavior standards.', "example"='Every agent loads the same agents/soul.md from the system home.', "definition"='Headers are Core Truths, How You Think, Vibe (with How It Sounds), Boundaries, and How We Work.', "source"='Ruled' WHERE name='base-soul' AND (storage_name LIKE '%/Code/agent-team/%' OR storage_name = 'team/soul.md');
UPDATE object_types SET "supertype"='view', "subtype"='schema', "lens"='knowledge', "container"='workspace', "module"='base', "storage_name"='SCHEMA.md', "description"='A generated page: every object type with its fields and meanings, plus the ERD.', "why"='Agents query the rows; the page is a readable view that nobody edits.', "example"='SCHEMA.md is built from the object_types and fields rows.', "definition"='Generated view in the dictionary collection. Change the rows, then rebuild the page.', "source"='Ruled' WHERE name='schema' AND supertype = 'contract';
-- T669: brand.md lives with the business. Guarded by the old value, so a second run changes nothing.
UPDATE object_types SET "module"='base', "storage_name"='config/brand.md', "example"='Sample Shop keeps its brand in sample-shop/config/brand.md.', "source"='base/dictionary-seed.sql' WHERE name='brand' AND storage_name = 'BRAND.md';
