-- T260: lessons. One row is one correction or lesson that every agent reads. The Keeper owns the table (g-capture-owns-raw-keeper-owns-memory-knowledge-and-lint). INSERT OR IGNORE only, so a second run changes nothing. memory/lessons.py apply runs this block.
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('lessons','database','table','knowledge','collection','memory','table','lessons','A lesson is one correction or rule that every agent reads, with its source and the person''s words.','Without lesson rows, a correction lives in one runtime''s private notes and other agents repeat the mistake.','L12: every task id carries its title; source: a Claude memory file; applies to all agents.','CREATE TABLE lessons ( id TEXT PRIMARY KEY CHECK (id GLOB ''L[1-9]*'' AND id NOT GLOB ''L*[^0-9]*''), text TEXT NOT NULL CHECK (length(trim(text)) > 0 AND instr(text, char(10)) = 0), person_words TEXT, source TEXT NOT NULL CHECK (length(trim(source)) > 0), workspace TEXT NOT NULL DEFAULT ''all'', applies_to TEXT NOT NULL DEFAULT ''all'', status TEXT NOT NULL DEFAULT ''active'' CHECK (status IN (''active'',''replaced'')), replaces TEXT REFERENCES lessons(id), created_on TEXT NOT NULL CHECK (date(created_on) = created_on), UNIQUE (source, text) )','Ruled');
INSERT OR IGNORE INTO object_types ("name","supertype","subtype","lens","container","module","database_type","storage_name","description","why","example","definition","source") VALUES ('active_lessons','database','view','knowledge','collection','memory','view','active_lessons','The active lessons, newest first. The start page lists them.','Agents read one list; replaced lessons drop out.','SELECT id,text FROM active_lessons WHERE applies_to=''all'';','CREATE VIEW active_lessons AS SELECT id, text, workspace, applies_to, source, created_on FROM lessons WHERE status = ''active'' ORDER BY created_on DESC, CAST(substr(id, 2) AS INTEGER) DESC','Ruled');
INSERT OR IGNORE INTO fields ("object_type","field","ordinal","required","field_type","pick_values","pick_source","description","storage_type","sql_definition","source") VALUES ('lessons','id',1,1,'key',NULL,NULL,'Identifies the lesson: L and a number, given by lesson-add.','TEXT','TEXT PRIMARY KEY CHECK (id GLOB ''L[1-9]*'' AND id NOT GLOB ''L*[^0-9]*'')','Ruled');
INSERT OR IGNORE INTO fields ("object_type","field","ordinal","required","field_type","pick_values","pick_source","description","storage_type","sql_definition","source") VALUES ('lessons','text',2,1,'text',NULL,NULL,'States the rule in one line.','TEXT','TEXT NOT NULL','Ruled');
